=|Campaign | Success Rate | Date | Error Types |
|--|--|--|--|
{{
$input.all().map((i)=>{
return  "|" + i.json.TARGET_MM_CAMPAIGN + " | " + i.json.SUCCESS_RATE + "% (" + i.json.TARGET_SUCCESS +"/" + i.json.INSTANCES +") |" + $if(i.json.ONEOFF_CAMPAIGN_LAUNCH_DATE, i.json.ONEOFF_CAMPAIGN_LAUNCH_DATE, " - ") + "| "+
($if((Number(i.json.ERROR_TARGET_EMPTY)>0 || Number(i.json.ERROR_TARGET_MINIMUM_NOT_MET)>0), "Empty Target", "") +
$if(Number(i.json.ERROR_STRONGVIEW_SHUTDOWN)>0, ", Strongmail Down", "") +
$if(Number(i.json.ERROR_TARGET_DELETED)>0, ", Target Deleted", "") +
$if(Number(i.json.ERROR_TEMPLATE_NAME)>0, ", Template Not Found", "") +
$if(Number(i.json.ERROR_TEMPLATE_NOT_APPROVED)>0, ", Template Not Approved", "") || "- ")

+ "|\n"
}).join("")  }}

